DO $m$ DECLARE d text; BEGIN SELECT pg_get_functiondef('hotel_private.hotel_review_action(uuid,text,jsonb)'::regprocedure) INTO d; d:=replace(d,'SET subtotal=total,total=total,extras=extras||jsonb_build_object(''payment_due'',ROUND(total*pct/100,2))','SET subtotal=hotel_review_action.total,total=hotel_review_action.total,extras=extras||jsonb_build_object(''payment_due'',ROUND(hotel_review_action.total*pct/100,2))'); EXECUTE d; END $m$;